	Cases     []refCase `json:"cases"`
	NFC       refCase   `json:"nfc"`
}

func loadCases(t *testing.T) *refCases {
	t.Helper()
	buf, err := os.ReadFile(filepath.Join(refDir, "cases.json"))
	if err != nil {
