// Command textenc runs Z-Image's text encoder: a prompt in, the hidden state
// the DiT's cap_embedder consumes out.
//
// It is the stage-5 vertical slice -- tokenizer and Qwen3-4B, both on the CPU
// -- and the thing it measures is why there has to be a stage 5c. The
// encoder is 3.5 B parameters over 35 layers for a prompt of a few dozen
// tokens, so unlike the DiT it is not compute-bound at all: at T tokens the
// arithmetic intensity of a projection is T flop/byte of weight against this
// device's 235 crossover (research/3.4-model-shapes.md), which puts every
// shape here deep in the memory-bound regime a GEMV kernel serves and a
// 128-row WMMA tile does not.
//
//	go run ./cmd/textenc -prompt "a cat on a windowsill"
package main

import (
	"flag"
	"fmt"
	"log"
	"math"
	"strings"
	"time"

	"strix-halo-vulkan/zimage/qwen"
	"strix-halo-vulkan/zimage/tokenizer"
)

func main() {
	log.SetFlags(0)
	encDir := flag.String("encoder", "models/Z-Image-Turbo/text_encoder", "text encoder checkpoint")
	tokDir := flag.String("tokenizer", "models/Z-Image-Turbo/tokenizer", "tokenizer directory")
	prompt := flag.String("prompt", "a cat sitting on a windowsill at golden hour, 85mm lens", "prompt")
	layers := flag.Int("layers", 0, "decoder layers to run; 0 is what the pipeline uses")
	reps := flag.Int("reps", 1, "timed repetitions of the forward pass; the best is reported")
	verbose := flag.Bool("v", false, "print the token ids")
	flag.Parse()

	tok, err := tokenizer.Load(*tokDir)
	must(err)
	ids, err := tok.EncodePrompt(*prompt)
	must(err)
	fmt.Printf("prompt   %q\n", *prompt)
	fmt.Printf("tokens   %d, including the chat template's 8\n", len(ids))
	if *verbose {
		var b strings.Builder
		for i, id := range ids {
			piece, err := tok.Decode([]int32{id})
			must(err)
			fmt.Fprintf(&b, "  %3d %6d  %q\n", i, id, piece)
		}
		fmt.Print(b.String())
	}

	cfg, err := qwen.LoadConfig(*encDir)
	must(err)
	n := *layers
	if n == 0 {
		n = cfg.EncoderLayers()
	}
	fmt.Printf("encoder  Qwen3-%d layers, hidden %d, %d/%d heads of %d, ffn %d\n",
		cfg.NumLayers, cfg.HiddenSize, cfg.NumHeads, cfg.NumKVHeads, cfg.HeadDim, cfg.IntermediateSize)
	fmt.Printf("running  %d layers -- hidden_states[-2], no final norm, no lm_head\n", n)

	start := time.Now()
	model, err := qwen.Load(*encDir, n)
	must(err)
	load := time.Since(start)

	best := time.Duration(math.MaxInt64)
	var out *qwen.Mat
	for i := 0; i < *reps; i++ {
		start = time.Now()
		out, err = model.Forward(ids, nil)
		must(err)
		if d := time.Since(start); d < best {
			best = d
		}
	}

	var sum, sumSq, absmax float64
	for _, v := range out.Data {
		sum += float64(v)
		sumSq += float64(v) * float64(v)
		if a := math.Abs(float64(v)); a > absmax {
			absmax = a
		}
	}
	rms := math.Sqrt(sumSq / float64(len(out.Data)))

	// Parameters actually multiplied: the layers, without the embedding
	// table, which is a gather and not a GEMM.
	perLayer := float64(cfg.HiddenSize) * float64(
		2*cfg.NumHeads*cfg.HeadDim+2*cfg.NumKVHeads*cfg.HeadDim+3*cfg.IntermediateSize)
	params := perLayer * float64(n)
	flops := 2 * params * float64(len(ids))

	fmt.Printf("\nhidden   %s  sum %+.4g  rms %.4g  absmax %.5g\n", out, sum, rms, absmax)
	fmt.Printf("weights  %.2f B parameters in the layers, %.2f GB as fp32, %.2f GB as fp16\n",
		params/1e9, params*4/1e9, params*2/1e9)
	fmt.Printf("load     %v\n", load.Round(time.Millisecond))
	fmt.Printf("forward  %v, best of %d -- %.1f GFLOP at %.2f GFLOP/s\n",
		best.Round(time.Millisecond), *reps, flops/1e9, flops/best.Seconds()/1e9)
	fmt.Printf("regime   %d flop per byte of fp16 weight against a 235 crossover: memory-bound,\n"+
		"         so the floor on this device is %.0f ms of weight traffic at 236 GB/s\n",
		len(ids), params*2/236e9*1e3)
}

func must(err error) {
	if err != nil {
		log.Fatal(err)
	}
}
