// cannot be read back out of the SPIR-V.
type gemmVariant struct {
	name  GEMMKernel
	spirv []byte
	bm    int // workgroup tile rows = WAVES_M * WM * 16
	bn    int // workgroup tile columns = WAVES_N * WN * 16
	waves int // waves per workgroup; > 1 pins the subgroup size
