	{name: GEMMReg64HKA4, spirv: shaders.DiTGEMMReg64HKA4, bm: 64, bn: 64, waves: 1, layout: 0},
	{name: GEMMReg64HKA4Tiled, spirv: shaders.DiTGEMMReg64HKA4Tiled, bm: 64, bn: 64, waves: 1, layout: 2},
