func NewGPUStack(dev *vk.Device, set *safetensors.Set, cfg *Config, rope *RoPE, tokens int, plan GEMMPlan) (*GPUStack, error) {
	return newStack(dev, set, cfg, StackBlocks(cfg), rope, tokens, plan, blockControls{}, maxBankBytes)
