	pcSize := uint32(unsafe.Sizeof(pushConstants{}))
	simple := map[string][]byte{
		"adaln":     shaders.DiTAdaLN,
		"rmsnorm":   shaders.DiTRMSNorm,
		"rope":      shaders.DiTRoPE,

