			len(rope.Cos), g.tokens*g.headDim/2)
	}
	g.wbuf.WriteFloat32At(int(g.wCos), rope.Cos)
	g.wbuf.WriteFloat32At(int(g.wSin), rope.Sin)
	return nil
}

