content.content:
=========== dit_rmsnorm
#version 450
// RMS norm over each span of pc.span components within a row, scaled by a
// learned weight of that width.
//
// One workgroup per (token, span). The span is the whole row for the block's
// four norms and one head for the q/k norms -- the same kernel, because the
// only thing that differs is how many spans a row holds. Getting that wrong
// is a real hazard: normalising q over the full 3840 instead of per 128-wide
// head is a plausible port bug that changes the output by 2.4x.

#include "dit_common.glsl"

layout(local_size_x = 256) in;

shared float partial[256];

float reduceSum(float v) {
    uint t = gl_LocalInvocationID.x;
    partial[t] = v;
    barrier();
    for (uint s = 128u; s > 0u; s >>= 1) {
        if (t < s) {
            partial[t] += partial[t + s];
        }
        barrier();
    }
    float r = partial[0];
    barrier();
    return r;
}

void main() {
    uint spans = pc.dim / pc.span;
    uint token = gl_WorkGroupID.x / spans;
    uint span = gl_WorkGroupID.x % spans;
    uint t = gl_LocalInvocationID.x;
    if (token >= pc.tokens) {
        return;
    }
    uint base = token * pc.dim + span * pc.span;

    // Each thread sums its own stride-256 slice before the tree reduction,
    // so a 3840-wide sum is a tree over partials rather than a serial chain.
    float s = 0.0;
    for (uint i = t; i < pc.span; i += 256u) {
        float v = act[pc.inOff + base + i];
        s += v * v;
    }
    float meanSq = reduceSum(s) / float(pc.span);
    float inv = inversesqrt(meanSq + uintBitsToFloat(pc.eps));

    for (uint i = t; i < pc.span; i += 256u) {
        act[pc.outOff + base + i] = act[pc.inOff + base + i] * inv * wbuf[pc.wOff + i];
    }
}
=========== dit_norm_scale_f16
#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
// A block input, end to end: RMS norm over the whole row, the adaLN scale,
// and the narrowing into the fp16 arena as a GEMM A operand.
//
// dit_rmsnorm.comp followed by dit_scale_f16.comp is the same arithmetic in
// two dispatches and 1.5x the traffic -- the fp32 intermediate is written and
// read back for nothing -- so this is one pass: read 63 MB, write 31 MB.
//
// The scale is `1 + mod`, already formed by dit_adaln.comp, and it lives in
// the *activation* arena because it is computed per step, which is why its
// offset is pc.aux0 and not pc.wOff. pc.aux2 = 0 drops it, which is the
// attention context's path into the output projection.
//
// The destination stride is pc.lda, not pc.dim: A's rows are K + 128 halves
// apart so that a K-strided fragment load does not put all 16 of its
// addresses in one DRAM channel (§2.3).

#include "dit_common.glsl"

layout(binding = 2) writeonly buffer HAct { float16_t hact[]; };

#define WG 256
layout(local_size_x = WG) in;

shared float partial[WG];

void main() {
    uint r = gl_WorkGroupID.x;
    uint t = gl_LocalInvocationID.x;
    if (r >= pc.tokens) {
        return;
    }
    uint src = pc.inOff + r * pc.dim;
    uint dst = pc.outOff + r * pc.lda;

    float s = 0.0;
    for (uint c = t; c < pc.dim; c += WG) {
        float v = act[src + c];
        s += v * v;
    }
    partial[t] = s;
    barrier();
    for (uint step = WG / 2u; step > 0u; step >>= 1) {
        if (t < step) {
